    static readonly Dictionary<string, Geometry[]> Cache = new();

    /// <summary>Descobre o ícone pelo nome do app/agente (ex.: "Claude Code", "OpenAI Codex", "ChatGPT").</summary>
    public static string? Match(string? name)
    {
        if (string.IsNullOrWhiteSpace(name)) return null;
        var n = name.ToLowerInvariant();
        if (n.Contains("codex")) return "codex";
        if (n.Contains("claude") || n.Contains("anthropic")) return "claude";
        if (n.Contains("chatgpt") || n.Contains("openai") || n.Contains("gpt")) return "openai";
        if (n.Contains("cursor")) return "cursor";
        if (n.Contains("gemini")) return "gemini";
        if (n.Contains("ollama")) return "ollama";
        if (n.Contains("lm studio") || n.Contains("lmstudio")) return "lmstudio";
        return null;
    }

    static Geometry[] Geos(string id)
    {
        if (Cache.TryGetValue(id, out var g)) return g;
        g = Icons[id].layers.Select(l => { var geo = Geometry.Parse("F0 " + l.data); geo.Freeze(); return geo; }).ToArray();
        return Cache[id] = g;
    }

    public static (Brush bg, Brush fg) Colors(string id) => (K.Hex(Icons[id].bg), K.Hex(Icons[id].fg));

    /// <summary>Só o logo (monocromático) com o tamanho pedido.</summary>
    public static UIElement Logo(string id, double size, Brush fg)
    {
        var geos = Geos(id);
        var grid = new Grid { Width = size, Height = size, IsHitTestVisible = false };
        for (int i = 0; i < geos.Length; i++)
            grid.Children.Add(new System.Windows.Shapes.Path { Data = geos[i], Fill = fg, Opacity = Icons[id].layers[i].opacity, Stretch = Stretch.Uniform });
        return grid;
    }

    /// <summary>Círculo "ícone de app" com a cor da marca e o logo por cima.</summary>
    public static Border Badge(string id, double size)
    {
        var (_, bg, fg) = Icons[id];
        return new Border
        {
            Width = size, Height = size, CornerRadius = new CornerRadius(size / 2), Background = K.Hex(bg),
            BorderBrush = K.Hex("#22FFFFFF"), BorderThickness = new Thickness(1),
            Child = Logo(id, size * 0.56, K.Hex(fg)), VerticalAlignment = VerticalAlignment.Center
        };
    }

    /// <summary>Badge da marca quando conhecida; senão, círculo colorido com a inicial.</summary>
    public static Border BadgeFor(string? name, string letter, string colorHex, double size)
    {
        var id = Match(name);
        if (id != null) return Badge(id, size);
        var t = K.T(string.IsNullOrEmpty(letter) ? "•" : letter, size * 0.42, Brushes.Black, true);
        t.HorizontalAlignment = HorizontalAlignment.Center; t.VerticalAlignment = VerticalAlignment.Center;
        return new Border { Width = size, Height = size, CornerRadius = new CornerRadius(size / 2), Background = K.Hex(colorHex), Child = t, VerticalAlignment = VerticalAlignment.Center };
    }

    // "✦" de IA genérico (desenho próprio, sem marca): estrela de 4 pontas com uma faísca pequena
    static readonly Geometry SparkleGeo = Make("F0 M 11,3 C 11.8,8.4 15.6,12.2 21,13 C 15.6,13.8 11.8,17.6 11,23 C 10.2,17.6 6.4,13.8 1,13 C 6.4,12.2 10.2,8.4 11,3 Z M 19.5,0.5 C 19.7,2 20.5,2.8 22,3 C 20.5,3.2 19.7,4 19.5,5.5 C 19.3,4 18.5,3.2 17,3 C 18.5,2.8 19.3,2 19.5,0.5 Z");
    static Geometry Make(string d) { var g = Geometry.Parse(d); g.Freeze(); return g; }
    public static System.Windows.Shapes.Path Sparkle(double size, Brush fg) => new() { Data = SparkleGeo, Fill = fg, Stretch = Stretch.Uniform, Width = size, Height = size };
}
